    27|// ── Crypto ─────────────────────────────────────────────────
    28|
    29|async function sha256(text: string): Promise<string> {
    30|  const data = new TextEncoder().encode(text);
    31|  const buf = await crypto.subtle.digest("SHA-256", data);
    32|  return Array.from(new Uint8Array(buf), (b) => b.toString(16).padStart(2, "0")).join("");
    33|}
    34|
    35|function generateOtp(): string {
    36|  const d = new Uint8Array(6);
    37|  crypto.getRandomValues(d);
    38|  return Array.from(d, (b) => (b % 10).toString()).join("");
    39|}
