    41|function generatePassword(): string {
    42|  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789!@#$";
    43|  const arr = new Uint8Array(20);
    44|  crypto.getRandomValues(arr);
    45|  return Array.from(arr, (b) => chars[b % chars.length]).join("");
